var n=`1018-pho-bo`;var s=`world-1018`;var o=`VN`;var t=`southeast-asia`;var a=4;var r=202;var l={en:`Pho Bo`,ua:`Фо бо`};var m={en:`Pho Bo is a dish from Vietnam prepared with beef bones, yellow onion, beef sirloin, fish sauce. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Фо бо, страва кухні країни В'єтнам, яку готують із таких продуктів: яловичі кістки, жовта цибуля, яловичий сирлойн, рибний соус. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var g=[{en:`Toast the whole spices briefly and simmer roasted onion, ginger and beef bones in clean water, skimming until the pho broth is clear and aromatic.`,ua:`Коротко прогрійте цілі спеції та томіть підпечені цибулю й імбир із яловичими кістками у чистій воді, знімаючи піну до прозорого ароматного бульйону.`,t:[`simmering`,`skimming-foam`],m:180,i:[[`beef-bones`,1250,`g`],[`water`,2400,`ml`],[`yellow-onion`,220,`g`],[`ground-ginger`,80,`g`],[`star-anise`,4,`pcs`],[`ceylon-cinnamon`,2,`pcs`],[`cardamom-pods`,4,`pcs`]]},{en:`Poach the listed ingredients in barely simmering liquid for about 12 minutes until tender and cooked through.`,ua:`Пошируйте зазначені продукти в рідині без бурхливого кипіння приблизно 12 хвилин до готовності й м’якості.`,t:[`poaching`],m:12,i:[[`beef-sirloin`,480,`g`],[`fish-sauce`,50,`ml`]]},{en:`Cook the listed ingredients in simmering water for about 6 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 6 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:6,i:[[`rice-noodles`,420,`g`],[`water`,1200,`ml`]]},{en:`Assemble the cooled components with the listed fillings or toppings. Refrigerate briefly if needed to set the layers.`,ua:`Зберіть охолоджені частини з зазначеними начинками або покриттям. За потреби ненадовго охолодіть для стабілізації шарів.`,t:[`layered-assembly`,`garnishing`],m:4,i:[[`bean-sprouts`,220,`g`],[`thai-basil`,35,`g`],[`lime`,2,`pcs`],[`cilantro`,25,`g`],[`green-onion`,35,`g`]]}];var d={slug:n,id:s,country:`VN`,region:t,servings:4,minutes:202,title:l,text:m,steps:g};export{o as country,d as default,s as id,r as minutes,t as region,a as servings,n as slug,g as steps,m as text,l as title};